"use client"

import { useState } from "react"

import { formatChartNumber } from "@/lib/chart-format"
import { clamp } from "@/lib/chart-geom"
import { seriesColor } from "@/lib/chart-series"
import {
  ChartCard,
  ChartLegend,
  ChartTip,
  chartStatusLabels,
  chartStatusLabelsEs,
  type ChartCardClassNames,
  type ChartStatus,
  type ChartStatusLabels,
} from "@/components/ui/chart-card"

export type RangeLane = { id: string; label: string; start: number; end: number; tone?: number }

export type RangeLanesLabels = ChartStatusLabels & {
  legend: string
  lane: (label: string, start: string, end: string) => string
  scale: string
}

export const rangeLanesLabels: RangeLanesLabels = {
  ...chartStatusLabels,
  legend: "Lanes",
  lane: (label, start, end) => `${label}: ${start} – ${end}`,
  scale: "Scale",
}

export const rangeLanesLabelsEs: RangeLanesLabels = {
  ...chartStatusLabelsEs,
  legend: "Carriles",
  lane: (label, start, end) => `${label}: ${start} – ${end}`,
  scale: "Escala",
}

export type RangeLanesProps = {
  title: string
  description?: string
  lanes: RangeLane[]
  domain?: { min: number; max: number }
  ticks?: { value: number; label: string }[]
  locale?: string
  status?: ChartStatus
  labels?: Partial<RangeLanesLabels>
  activeId?: string | null
  onActiveChange?: (id: string | null) => void
  onMenu?: () => void
  onRetry?: () => void
  className?: string
  classNames?: ChartCardClassNames
}

export function RangeLanes({
  title,
  description,
  lanes,
  domain,
  ticks,
  locale,
  status = "ready",
  labels,
  activeId,
  onActiveChange,
  onMenu,
  onRetry,
  className,
  classNames,
}: RangeLanesProps) {
  const copy = { ...rangeLanesLabels, ...labels }
  const [internal, setInternal] = useState<string | null>(null)
  const [tip, setTip] = useState<{ id: string; x: number } | null>(null)
  const active = activeId !== undefined ? activeId : internal
  const empty = lanes.length === 0
  const view = status !== "ready" ? status : empty ? "empty" : "ready"
  const min = domain?.min ?? Math.min(0, ...lanes.flatMap((lane) => [lane.start, lane.end]))
  const max = domain?.max ?? Math.max(1, ...lanes.flatMap((lane) => [lane.start, lane.end]))
  const span = max - min || 1

  function setActive(id: string | null) {
    if (activeId === undefined) setInternal(id)
    onActiveChange?.(id)
  }

  function place(value: number) {
    return `${clamp((value - min) / span, 0, 1) * 100}%`
  }

  const hovered = lanes.find((lane) => lane.id === tip?.id)

  return (
    <ChartCard
      title={title}
      description={description}
      status={view}
      labels={copy}
      onMenu={onMenu}
      onRetry={onRetry}
      className={className}
      classNames={classNames}
      summary={lanes.map((lane) => copy.lane(lane.label, formatChartNumber(lane.start, locale), formatChartNumber(lane.end, locale))).join(". ")}
      columns={[
        { id: "start", label: "Start" },
        { id: "end", label: "End" },
      ]}
      rows={lanes.map((lane) => ({
        id: lane.id,
        label: lane.label,
        cells: { start: formatChartNumber(lane.start, locale), end: formatChartNumber(lane.end, locale) },
      }))}
      live={hovered ? copy.lane(hovered.label, formatChartNumber(hovered.start, locale), formatChartNumber(hovered.end, locale)) : undefined}
      legend={
        <ChartLegend
          label={copy.legend}
          activeId={active}
          onActiveChange={setActive}
          items={lanes.map((lane, index) => ({ id: lane.id, label: lane.label, tone: lane.tone ?? index }))}
        />
      }
    >
      <div className="relative flex flex-col gap-2" role="listbox" aria-label={title}>
        {ticks && ticks.length > 0 ? (
          <div className="grid grid-cols-[5.5rem_1fr] text-[10px] text-muted-foreground" aria-hidden>
            <span />
            <span className="relative h-4">
              {ticks.map((tick) => (
                <span key={tick.value} className="absolute -translate-x-1/2" style={{ left: place(tick.value) }}>
                  {tick.label}
                </span>
              ))}
            </span>
          </div>
        ) : null}
        {lanes.map((lane, index) => {
          const start = Math.min(lane.start, lane.end)
          const end = Math.max(lane.start, lane.end)
          const startRatio = clamp((start - min) / span, 0, 1)
          const endRatio = clamp((end - min) / span, 0, 1)
          const strong = active == null || active === lane.id
          return (
            <button
              key={lane.id}
              type="button"
              role="option"
              data-slot="range-lane"
              aria-selected={active === lane.id}
              aria-label={copy.lane(lane.label, formatChartNumber(start, locale), formatChartNumber(end, locale))}
              className="grid h-8 w-full grid-cols-[5.5rem_1fr] items-center gap-2 rounded-lg bg-muted/50 px-2 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring"
              onMouseEnter={(event) => {
                const rect = event.currentTarget.getBoundingClientRect()
                setTip({ id: lane.id, x: event.clientX - rect.left })
              }}
              onMouseLeave={() => setTip(null)}
              onFocus={() => setActive(lane.id)}
              onClick={() => setActive(active === lane.id ? null : lane.id)}
            >
              <span className="truncate text-xs">{lane.label}</span>
              <span className="relative h-full">
                <span
                  aria-hidden
                  data-slot="range-lane-bar"
                  className="absolute top-1/2 h-2.5 w-full origin-left rounded-md motion-safe:transition-transform motion-safe:duration-300 motion-reduce:transition-none"
                  style={{
                    transform: `translate(${startRatio * 100}%, -50%) scaleX(${Math.max(0.02, endRatio - startRatio)})`,
                    transformOrigin: "left center",
                    background: strong ? seriesColor(lane.tone ?? index) : "var(--muted-foreground)",
                  }}
                />
              </span>
            </button>
          )
        })}
        <ChartTip open={hovered != null} x={tip?.x ?? 0} y={0}>
          {hovered ? copy.lane(hovered.label, formatChartNumber(Math.min(hovered.start, hovered.end), locale), formatChartNumber(Math.max(hovered.start, hovered.end), locale)) : null}
        </ChartTip>
      </div>
    </ChartCard>
  )
}

"use client"

import { useId, useLayoutEffect, useRef, useState, useSyncExternalStore, type KeyboardEvent, type ReactNode } from "react"
import { CircleAlert, MoreHorizontal } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"
import { chartFigureParts, type ChartKpiFigure } from "@/lib/chart-format"
import { SeriesSwatch } from "@/components/ui/chart-marks"

const REDUCE_QUERY = "(prefers-reduced-motion: reduce)"

function subscribeReduced(onStoreChange: () => void) {
  const media = window.matchMedia(REDUCE_QUERY)
  media.addEventListener("change", onStoreChange)
  return () => media.removeEventListener("change", onStoreChange)
}

export function usePrefersReducedMotion() {
  return useSyncExternalStore(subscribeReduced, () => window.matchMedia(REDUCE_QUERY).matches, () => false)
}

export function chartTransition(reduced: boolean) {
  if (reduced) return { duration: 0 }
  return { duration: motionPresets.duration.considered, ease: [...motionPresets.ease.enter] as [number, number, number, number] }
}

export type ChartStatus = "ready" | "loading" | "empty" | "error"

export type ChartStatusLabels = {
  loading: string
  empty: string
  error: string
  retry: string
  more: string
}

export const chartStatusLabels: ChartStatusLabels = {
  loading: "Loading",
  empty: "Nothing to show yet",
  error: "Could not load this chart",
  retry: "Try again",
  more: "More",
}

export const chartStatusLabelsEs: ChartStatusLabels = {
  loading: "Cargando",
  empty: "Todavía no hay datos",
  error: "No se pudo cargar el gráfico",
  retry: "Reintentar",
  more: "Más",
}

export type ChartSummaryColumn = { id: string; label: string }
export type ChartSummaryRow = { id: string; label: string; cells: Record<string, string> }

export type ChartCardClassNames = {
  root?: string
  header?: string
  title?: string
  description?: string
  kpis?: string
  controls?: string
  body?: string
  legend?: string
  insight?: string
  footer?: string
}

export type ChartCardProps = {
  title: string
  description?: string
  status?: ChartStatus
  labels?: Partial<ChartStatusLabels>
  onRetry?: () => void
  menuLabel?: string
  onMenu?: () => void
  menu?: ReactNode
  kpis?: ReactNode
  controls?: ReactNode
  legend?: ReactNode
  insight?: ReactNode
  footer?: ReactNode
  /** One-sentence description of the data, read with the chart. */
  summary: string
  tableCaption?: string
  columns?: ChartSummaryColumn[]
  rows?: ChartSummaryRow[]
  live?: string
  children?: ReactNode
  className?: string
  classNames?: ChartCardClassNames
}

export function ChartCard({
  title,
  description,
  status = "ready",
  labels,
  onRetry,
  menuLabel,
  onMenu,
  menu,
  kpis,
  controls,
  legend,
  insight,
  footer,
  summary,
  tableCaption,
  columns,
  rows,
  live,
  children,
  className,
  classNames,
}: ChartCardProps) {
  const uid = useId().replace(/:/g, "")
  const titleId = `${uid}-title`
  const summaryId = `${uid}-summary`
  const copy = { ...chartStatusLabels, ...labels }
  const root = `[data-chart-card="${uid}"]`

  return (
    <Card
      data-slot="chart-card"
      data-chart-card={uid}
      data-status={status}
      aria-labelledby={titleId}
      aria-describedby={summaryId}
      className={cn("w-full min-w-0 gap-3 py-4", classNames?.root, className)}
    >
      <style>{`
        @keyframes rui-scale-y { from { transform: scaleY(0); opacity: 0; } }
        @keyframes rui-scale-x { from { transform: scaleX(0); opacity: 0; } }
        @keyframes rui-polar-in { from { opacity: 0; transform: scale(0.96); } }
        @media (prefers-reduced-motion: reduce) {
          ${root}, ${root} * {
            animation: none !important;
            transition: none !important;
          }
        }
      `}</style>
      <header className={cn("flex items-start gap-3 px-4", classNames?.header)}>
        <div className="min-w-0 max-w-[17.5rem] flex-1">
          <h2 id={titleId} data-slot="chart-card-title" className={cn("truncate text-base font-medium leading-snug", classNames?.title)}>
            {title}
          </h2>
          {description ? (
            <p className={cn("mt-0.5 text-xs text-muted-foreground", classNames?.description)}>{description}</p>
          ) : null}
        </div>
        {menu ??
          (onMenu ? (
            <Button type="button" variant="ghost" size="icon-xs" aria-label={menuLabel ?? copy.more} onClick={onMenu}>
              <MoreHorizontal />
            </Button>
          ) : null)}
      </header>
      {kpis ? <div className={cn("grid grid-cols-2 gap-3 px-4 sm:grid-cols-3", classNames?.kpis)}>{kpis}</div> : null}
      {controls ? <div className={cn("px-4", classNames?.controls)}>{controls}</div> : null}
      <div className={cn("min-w-0 px-4", classNames?.body)}>
        {status === "ready" ? (
          children
        ) : (
          <ChartState status={status} label={copy[status]} onRetry={status === "error" ? onRetry : undefined} retryLabel={copy.retry} />
        )}
      </div>
      {status === "ready" && legend ? <div className={cn("px-4", classNames?.legend)}>{legend}</div> : null}
      {status === "ready" && insight ? <div className={cn("max-w-[17.5rem] px-4", classNames?.insight)}>{insight}</div> : null}
      {status === "ready" && footer ? <div className={cn("flex flex-wrap items-center gap-2 px-4", classNames?.footer)}>{footer}</div> : null}
      <p id={summaryId} className="sr-only">
        {summary}
      </p>
      {live ? (
        <p className="sr-only" aria-live="polite" aria-atomic="true" data-slot="chart-live">
          {live}
        </p>
      ) : null}
      {columns && rows && rows.length > 0 ? (
        <table className="sr-only">
          {tableCaption ? <caption>{tableCaption}</caption> : null}
          <thead>
            <tr>
              <th scope="col">{tableCaption ?? title}</th>
              {columns.map((column) => (
                <th key={column.id} scope="col">
                  {column.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.id}>
                <th scope="row">{row.label}</th>
                {columns.map((column) => (
                  <td key={column.id}>{row.cells[column.id] ?? ""}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      ) : null}
    </Card>
  )
}

export function ChartState({
  status,
  label,
  onRetry,
  retryLabel,
}: {
  status: Exclude<ChartStatus, "ready">
  label: string
  onRetry?: () => void
  retryLabel: string
}) {
  return (
    <div
      data-slot="chart-state"
      data-status={status}
      className="flex min-h-36 flex-col items-center justify-center gap-3 rounded-xl bg-muted px-4 py-6 text-center"
      role={status === "error" ? "alert" : "status"}
    >
      {status === "loading" ? (
        <div className="flex h-16 items-end gap-1.5" aria-hidden>
          {[40, 70, 52, 88, 60].map((height) => (
            <span key={height} className="w-3 rounded-sm bg-muted motion-safe:animate-pulse" style={{ height }} />
          ))}
        </div>
      ) : null}
      {status === "error" ? <CircleAlert className="size-5 text-foreground" aria-hidden /> : null}
      <p className="max-w-[17.5rem] text-sm text-foreground">{label}</p>
      {onRetry ? (
        <Button type="button" size="sm" variant="outline" onClick={onRetry}>
          {retryLabel}
        </Button>
      ) : null}
    </div>
  )
}

export type { ChartKpiFigure }

function ChartKpiFigureView({ figure, quiet }: { figure: ChartKpiFigure; quiet?: boolean }) {
  const hierarchy = figure.hierarchy !== false
  const announce = figure.announce !== false
  const parts = chartFigureParts(figure)
  return (
    <span data-slot="chart-kpi-figure" data-hierarchy={hierarchy ? "on" : "off"} className="inline-flex max-w-full items-baseline">
      {announce ? <span className="sr-only">{parts.text}</span> : null}
      <span aria-hidden="true" className="inline-flex min-w-0 items-baseline">
        <span data-slot="chart-kpi-integer" className={hierarchy && !quiet ? "font-semibold" : undefined}>
          {parts.integer}
        </span>
        {parts.fraction ? (
          <span data-slot="chart-kpi-fraction" className={hierarchy ? "text-[0.65em] font-normal text-muted-foreground" : undefined}>
            {parts.fraction}
          </span>
        ) : null}
        {figure.suffix ? <span data-slot="chart-kpi-suffix">{figure.suffix}</span> : null}
      </span>
    </span>
  )
}

export function ChartKpi({
  label,
  value,
  figure,
  hint,
  emphasis = "primary",
}: {
  label: string
  /** Preformatted fallback. Prefer `figure` so the integer and the fraction stay apart. */
  value?: string
  figure?: ChartKpiFigure
  hint?: string
  /** `quiet` is the secondary figure: smaller and lighter than the primary KPI. */
  emphasis?: "primary" | "quiet"
}) {
  const quiet = emphasis === "quiet"
  return (
    <div data-slot="chart-kpi" data-emphasis={emphasis} className="min-w-0">
      <p className="truncate text-xs font-normal text-muted-foreground">{label}</p>
      <p
        className={cn(
          "truncate tabular-nums",
          quiet ? "text-sm font-normal text-muted-foreground" : "text-xl font-semibold tracking-tight",
        )}
      >
        {figure ? <ChartKpiFigureView figure={figure} quiet={quiet} /> : value}
      </p>
      {hint ? <p className="truncate text-xs font-normal text-muted-foreground">{hint}</p> : null}
    </div>
  )
}

export function ChartInsight({
  title,
  body,
  action,
}: {
  title: string
  body: string
  action?: ReactNode
}) {
  return (
    <div data-slot="chart-insight" className="flex items-start gap-3 rounded-xl bg-muted/70 p-3">
      <div className="min-w-0 flex-1">
        <p className="text-sm font-medium">{title}</p>
        <p className="text-sm text-muted-foreground">{body}</p>
      </div>
      {action}
    </div>
  )
}

export type ChartLegendItem = {
  id: string
  label: string
  value?: string
  tone: number
}

export function ChartLegend({
  label,
  items,
  activeId,
  onActiveChange,
}: {
  label: string
  items: ChartLegendItem[]
  activeId?: string | null
  onActiveChange?: (id: string | null) => void
}) {
  const [focus, setFocus] = useState(0)
  const refs = useRef<Array<HTMLButtonElement | null>>([])

  function select(index: number) {
    const item = items[index]
    if (!item) return
    setFocus(index)
    refs.current[index]?.focus()
    onActiveChange?.(activeId === item.id ? null : item.id)
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (!items.length) return
    const keys = ["ArrowRight", "ArrowLeft", "ArrowUp", "ArrowDown", "Home", "End"]
    if (!keys.includes(event.key)) return
    event.preventDefault()
    const next =
      event.key === "Home" ? 0 : event.key === "End" ? items.length - 1 : event.key === "ArrowRight" || event.key === "ArrowDown" ? (focus + 1) % items.length : (focus - 1 + items.length) % items.length
    select(next)
  }

  return (
    <div role="toolbar" aria-label={label} data-slot="chart-legend" className="flex flex-wrap gap-2" onKeyDown={onKeyDown}>
      {items.map((item, index) => {
        const pressed = activeId === item.id
        return (
          <button
            key={item.id}
            ref={(node) => {
              refs.current[index] = node
            }}
            type="button"
            data-slot="chart-legend-item"
            aria-pressed={pressed}
            tabIndex={index === focus ? 0 : -1}
            className={cn(
              "inline-flex max-w-full min-w-0 items-center gap-1.5 rounded-md px-2 py-1 text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring",
              pressed ? "bg-muted ring-1 ring-foreground/20" : "hover:bg-muted/70",
            )}
            onClick={() => select(index)}
          >
            <SeriesSwatch index={item.tone} />
            <span className="truncate">{item.label}</span>
            {item.value ? <span className="font-medium tabular-nums text-foreground">{item.value}</span> : null}
          </button>
        )
      })}
    </div>
  )
}

export function ChartTip({
  open,
  x,
  y,
  children,
}: {
  open: boolean
  x: number | string
  y: number | string
  children: ReactNode
}) {
  if (!open) return null
  return (
    <div
      data-slot="chart-tip"
      role="tooltip"
      className="pointer-events-none absolute z-10 max-w-[14rem] rounded-lg bg-foreground px-2.5 py-1.5 text-xs text-background shadow-md"
      style={{ left: x, top: y, transform: "translate(-50%, -110%)" }}
    >
      {children}
    </div>
  )
}

/** Measured plot width. `node` is the element ref; read `node.current` only in effects and events. */
export function usePlotBox(fallbackWidth = 320, fallbackHeight = 180) {
  const node = useRef<HTMLDivElement>(null)
  const [width, setWidth] = useState(fallbackWidth)
  useLayoutEffect(() => {
    const element = node.current
    if (!element) return
    const read = () => {
      const next = element.clientWidth
      if (next > 0) setWidth(next)
    }
    read()
    const observer = new ResizeObserver(read)
    observer.observe(element)
    return () => observer.disconnect()
  }, [fallbackHeight])
  return { node, width }
}

export function dimOpacity(active: boolean) {
  return active ? 1 : 0.18
}

/** Fixed graphic. The keyframe enters from 0. Later value changes transition the transform. */
export function chartScaleStyle(reduced: boolean, scale: number, origin: string, axis: "x" | "y" = "y") {
  const safe = Number.isFinite(scale) ? scale : 0
  const ease = motionPresets.ease.enter.join(", ")
  const duration = motionPresets.duration.considered
  const name = axis === "x" ? "rui-scale-x" : "rui-scale-y"
  return {
    "data-scale": String(Math.round(safe * 1000) / 1000),
    style: {
      transformBox: "view-box" as const,
      transformOrigin: origin,
      transform: axis === "x" ? `scaleX(${safe})` : `scaleY(${safe})`,
      opacity: 1,
      animation: reduced ? "none" : `${name} ${duration}s cubic-bezier(${ease})`,
      transition: reduced ? "none" : `transform ${duration}s cubic-bezier(${ease}), opacity ${duration}s cubic-bezier(${ease})`,
    },
  }
}

import { seriesColor, seriesMark, seriesPatternId } from "@/lib/chart-series"
import { cn } from "@/lib/utils"

const MARKS = [0, 1, 2, 3, 4]

/** SVG patterns. Each series pairs a chart token with a distinct mark. */
export function SeriesPatterns({ id }: { id: string }) {
  return (
    <defs>
      {MARKS.map((mark) => (
        <pattern key={mark} id={`${id}-mark-${mark}`} width="6" height="6" patternUnits="userSpaceOnUse">
          <rect width="6" height="6" fill={`var(--chart-${mark + 1})`} />
          {mark === 1 ? <path d="M0 6 L6 0" stroke="var(--foreground)" strokeOpacity="0.55" /> : null}
          {mark === 2 ? <circle cx="2" cy="2" r="1" fill="var(--foreground)" fillOpacity="0.55" /> : null}
          {mark === 3 ? <path d="M0 3 H6" stroke="var(--foreground)" strokeOpacity="0.5" /> : null}
          {mark === 4 ? <path d="M0 6 L6 0 M0 0 L6 6" stroke="var(--foreground)" strokeOpacity="0.45" /> : null}
        </pattern>
      ))}
    </defs>
  )
}

export function seriesPaint(prefix: string, index: number) {
  return `url(#${seriesPatternId(prefix, index)})`
}

export function SeriesSwatch({ index, className }: { index: number; className?: string }) {
  const mark = seriesMark(index)
  const image =
    mark === 1
      ? "repeating-linear-gradient(45deg, transparent, transparent 2px, var(--foreground) 2px, var(--foreground) 3px)"
      : mark === 2
        ? "radial-gradient(circle at 30% 30%, var(--foreground) 0.8px, transparent 1px)"
        : mark === 3
          ? "repeating-linear-gradient(0deg, transparent, transparent 2px, var(--foreground) 2px, var(--foreground) 3px)"
          : mark === 4
            ? "repeating-linear-gradient(45deg, transparent, transparent 2px, var(--foreground) 2px, var(--foreground) 3px), repeating-linear-gradient(-45deg, transparent, transparent 2px, var(--foreground) 2px, var(--foreground) 3px)"
            : undefined
  return (
    <span
      aria-hidden
      data-slot="chart-swatch"
      data-mark={mark}
      className={cn("inline-block size-2.5 shrink-0 rounded-[3px] ring-1 ring-foreground/15", className)}
      style={{ backgroundColor: seriesColor(index), backgroundImage: image }}
    />
  )
}

export type ChartLocale = string

const numberFormat = new Map<string, Intl.NumberFormat>()
const percentFormat = new Map<string, Intl.NumberFormat>()
const currencyFormat = new Map<string, Intl.NumberFormat>()

function cached(map: Map<string, Intl.NumberFormat>, key: string, create: () => Intl.NumberFormat) {
  let format = map.get(key)
  if (!format) {
    format = create()
    map.set(key, format)
  }
  return format
}

/** `es` and `en` map to es-MX and en-US. Any other BCP 47 tag is used as-is. */
export function resolveChartLocale(locale: ChartLocale | undefined): string {
  if (!locale || locale === "en") return "en-US"
  if (locale === "es") return "es-MX"
  return locale
}

export function formatChartNumber(value: number, locale: ChartLocale | undefined, digits = 1): string {
  const safe = Number.isFinite(value) ? value : 0
  const tag = resolveChartLocale(locale)
  const fraction = Number.isInteger(safe) ? 0 : digits
  const format = cached(numberFormat, `${tag}:${fraction}`, () =>
    new Intl.NumberFormat(tag, { maximumFractionDigits: fraction, minimumFractionDigits: 0 }),
  )
  return format.format(safe)
}

/** `share` is a ratio, 0.1 → 10%. */
export function formatChartPercent(share: number, locale: ChartLocale | undefined, digits = 0): string {
  const safe = Number.isFinite(share) ? share : 0
  const tag = resolveChartLocale(locale)
  const format = cached(percentFormat, `${tag}:${digits}`, () =>
    new Intl.NumberFormat(tag, { style: "percent", maximumFractionDigits: digits, minimumFractionDigits: 0 }),
  )
  return format.format(safe)
}

export function formatChartCurrency(value: number, locale: ChartLocale | undefined, currency: string): string {
  const safe = Number.isFinite(value) ? value : 0
  const tag = resolveChartLocale(locale)
  const format = cached(currencyFormat, `${tag}:${currency}`, () =>
    new Intl.NumberFormat(tag, { style: "currency", currency, maximumFractionDigits: 0 }),
  )
  return format.format(safe)
}

export type ChartUnit = {
  id: string
  label: string
  /** Multiplies the raw measure. Defaults to 1. */
  scale?: number
  /** When set, values format as money in this ISO currency. */
  currency?: string
  /** Appended after a plain number, such as "kg". */
  suffix?: string
}

export function formatChartUnit(value: number, unit: ChartUnit | undefined, locale: ChartLocale | undefined): string {
  const scaled = value * (unit?.scale ?? 1)
  if (unit?.currency) return formatChartCurrency(scaled, locale, unit.currency)
  const text = formatChartNumber(scaled, locale)
  return unit?.suffix ? `${text} ${unit.suffix}` : text
}

/**
 * Unflattened figure. `value`, `decimals`, `locale`, `prefix`, `suffix`,
 * `hierarchy`, and `announce` match NumberRoll. Percent and currency stay
 * here so callers do not preformat. The reel replaces the draw when #59 lands.
 */
export type ChartKpiFigure = {
  value: number
  decimals?: number
  locale?: ChartLocale
  prefix?: string
  suffix?: string
  /** `value` is a ratio. 0.1 is 10%. */
  percent?: boolean
  currency?: string
  hierarchy?: boolean
  announce?: boolean
}

const figureFormat = new Map<string, Intl.NumberFormat>()

function figureFormatter(figure: ChartKpiFigure, safe: number) {
  const tag = resolveChartLocale(figure.locale)
  if (figure.currency) {
    return cached(figureFormat, `c:${tag}:${figure.currency}`, () =>
      new Intl.NumberFormat(tag, {
        style: "currency",
        currency: figure.currency,
        maximumFractionDigits: 0,
        minimumFractionDigits: 0,
      }),
    )
  }
  if (figure.percent) {
    const digits = figure.decimals ?? 0
    return cached(figureFormat, `p:${tag}:${digits}`, () =>
      new Intl.NumberFormat(tag, { style: "percent", maximumFractionDigits: digits, minimumFractionDigits: 0 }),
    )
  }
  const digits = figure.decimals ?? 1
  const maximum = figure.decimals == null ? (Number.isInteger(safe) ? 0 : digits) : Math.min(8, Math.max(0, Math.trunc(figure.decimals)))
  return cached(figureFormat, `n:${tag}:${maximum}`, () =>
    new Intl.NumberFormat(tag, { maximumFractionDigits: maximum, minimumFractionDigits: 0 }),
  )
}

/** Integer, fraction (with the percent sign), and the full announced string. */
export function chartFigureParts(figure: ChartKpiFigure): { text: string; integer: string; fraction: string } {
  const safe = Number.isFinite(figure.value) ? figure.value : 0
  const format = figureFormatter(figure, safe)
  let integer = ""
  let fraction = ""
  for (const part of format.formatToParts(safe)) {
    if (part.type === "decimal" || part.type === "fraction" || part.type === "percentSign") fraction += part.value
    else integer += part.value
  }
  const prefix = figure.prefix ?? ""
  const suffix = figure.suffix ?? ""
  return {
    text: `${prefix}${format.format(safe)}${suffix}`,
    integer: `${prefix}${integer}`,
    fraction,
  }
}

export function chartFigureForUnit(value: number, unit: ChartUnit | undefined, locale: ChartLocale | undefined): ChartKpiFigure {
  const scaled = value * (unit?.scale ?? 1)
  if (unit?.currency) return { value: scaled, currency: unit.currency, locale, hierarchy: true, announce: true }
  return { value: scaled, locale, suffix: unit?.suffix ? ` ${unit.suffix}` : undefined, hierarchy: true, announce: true }
}

import { chartVar, type ChartTone } from "@/lib/chart-tone"

/** Host series palette. Charts cycle `--chart-1` … `--chart-5`. */
export const SERIES_COUNT = 5

export function seriesTone(index: number): ChartTone {
  const tone = (Math.abs(index) % SERIES_COUNT) + 1
  return tone as ChartTone
}

export function seriesColor(index: number): string {
  return chartVar(seriesTone(index))
}

/**
 * Non-color cue so a series is not identified by hue alone.
 * 0 solid, 1 diagonal, 2 dots, 3 horizontal, 4 cross.
 */
export function seriesMark(index: number): number {
  return Math.abs(index) % SERIES_COUNT
}

export function seriesPatternId(prefix: string, index: number): string {
  return `${prefix}-mark-${seriesMark(index)}`
}

/** shadcn chart tokens. Hosts define --chart-1 … --chart-5. */
export const CHART_TONES = [1, 2, 3, 4, 5] as const

export type ChartTone = (typeof CHART_TONES)[number]

export function chartVar(tone: ChartTone = 1): string {
  return `var(--chart-${tone})`
}

export function chartBgClass(tone: ChartTone = 1): string {
  switch (tone) {
    case 1:
      return "bg-chart-1"
    case 2:
      return "bg-chart-2"
    case 3:
      return "bg-chart-3"
    case 4:
      return "bg-chart-4"
    case 5:
      return "bg-chart-5"
  }
}

export function chartFillClass(tone: ChartTone = 1): string {
  switch (tone) {
    case 1:
      return "fill-chart-1"
    case 2:
      return "fill-chart-2"
    case 3:
      return "fill-chart-3"
    case 4:
      return "fill-chart-4"
    case 5:
      return "fill-chart-5"
  }
}

